package rpc

import (
 "context"
 "testing"
 "github.com/WuKongIM/WuKongIM/pkg/transport/internal/core"
)

// BenchmarkAdmissionRejection isolates real Enqueue rejection with fixed service
// state and reusable caller buffers. No pump runs because admission always fails.
func BenchmarkAdmissionRejection(b *testing.B) {
 for _, mode := range []string{"items", "queue_bytes", "retained_bytes", "canceled", "stopped", "payload"} {
  b.Run(mode, func(b *testing.B) {
   for _, parallel := range []bool{false, true} {
    name := "serial"; if parallel { name = "parallel" }
    b.Run(name, func(b *testing.B) {
     ctx, cancel := context.WithCancel(context.Background()); defer cancel()
     s := &Service{ctx:ctx, opts:core.ServiceOptions{QueueSize:1, MaxQueueBytes:64, MaxRetainedBytes:64, MaxPayload:64}}
     expected := core.ErrBusy
     switch mode {
     case "items": s.queuedItems=1
     case "queue_bytes": s.queuedBytes=64
     case "retained_bytes": s.retainedBytes=64
     case "canceled": cancel(); expected=core.ErrCanceled
     case "stopped": s.stopped=true; expected=core.ErrStopped
     case "payload": s.opts.MaxPayload=1; expected=core.ErrMsgTooLarge
     }
     req:=Request{Payload:core.NewOwnedBuffer(make([]byte,64),nil)}
     call:=func(){if err:=s.Enqueue(req); err!=expected {b.Fatalf("got %v, want %v",err,expected)}}
     b.ReportAllocs(); b.ResetTimer()
     if parallel {b.RunParallel(func(pb *testing.PB){for pb.Next(){call()}})} else {for i:=0;i<b.N;i++{call()}}
    })
   }
  })
 }
}

